<script setup lang="ts">import {onMounted,ref} from 'vue';import {request} from '../../api/http';const item=ref<any>(null),schedules=ref<any[]>([]),error=ref(''),doctorId=ref('');function book(id:number){uni.navigateTo({url:'/pages/booking/index?doctorId='+doctorId.value+'&scheduleId='+id});}onMounted(async()=>{try{const pages=getCurrentPages();const current=pages[pages.length-1] as unknown as {options?:{id?:string}};const id=current?.options?.id||'';doctorId.value=id;const [doctor,plan]=await Promise.all([request<any>({url:`/public/doctors/${id}`}),request<any>({url:`/public/doctors/${id}/schedules`,data:{page:1,pageSize:14}})]);item.value=doctor.data;schedules.value=plan.data.records;}catch{error.value='医生不存在或未发布';}});</script><template><view class="page"><view v-if="error">{{error}}</view><view v-else-if="!item">正在加载…</view><view v-else class="card"><text class="name">{{item.name}} {{item.title}}</text><text>{{item.departments.map((x:any)=>x.name).join('、')}}</text><text class="heading">个人简介</text><text>{{item.profile||'暂无公开简介'}}</text><text class="heading">未来出诊</text><view v-if="!schedules.length">暂无已发布的未来出诊</view><button v-for="schedule in schedules" :key="schedule.id" :disabled="schedule.availableQuota<1" @click="book(schedule.id)">{{schedule.scheduleDate}} {{schedule.sessionName}} · 剩余 {{schedule.availableQuota}} 号</button></view></view></template><style scoped>.page{padding:28rpx}.card{display:flex;flex-direction:column;gap:18rpx;padding:28rpx;background:#fff;border-radius:16rpx;color:#64748b}.name{font-size:38rpx;color:#17324d;font-weight:700}.heading{color:#17324d;font-weight:700;margin-top:16rpx}</style>
